), questions_added AS (
 INSERT INTO public.intensive_questions
 (id,course_id,exam_category,skill,type,difficulty,prompt,grading_mode,marks,
 reference_source,reference_unit,reference_page,reference_evidence,tags,is_active)
 SELECT md5('NUMO:EL097:FINAL:'||(row->>'part')||':'||(row->>'id'))::uuid,
 (SELECT id FROM public.intensive_courses WHERE code='EL097_EL099E'),
 'FINAL', row->>'part','MULTIPLE_CHOICE','MEDIUM',row->>'prompt','AUTO',1,
 'NUMO EL097 Final Answered Question Bank · 4 source collections',
 row->>'part',COALESCE(substring(row->>'source' FROM 'p\\.([0-9]+)'), 'original file'),
 CASE WHEN coalesce(row->>'note','')<>'' THEN 'EL097_FINAL_SOURCE_NOTE: '||(row->>'note') ELSE NULL END,
 ARRAY['EL097-FINAL','SKILL='||(row->>'part'),'SOURCE_Q='||(row->>'id'), 'SOURCE='||(row->>'source')],
 (row->>'key') IS NOT NULL
 FROM dataset ON CONFLICT(id) DO NOTHING RETURNING id
), options_added AS (
 INSERT INTO public.intensive_question_options (id,question_id,label,value,is_correct,position)
 SELECT md5('NUMO:EL097:FINAL:'||(d.row->>'part')||':'||(d.row->>'id')||':OPTION:'||(o.value->>'label'))::uuid,
 q.id,o.value->>'label',o.value->>'text',
 (o.value->>'label')=(d.row->>'key'),ascii(o.value->>'label')-96
 FROM dataset d JOIN questions_added q ON q.id=md5('NUMO:EL097:FINAL:'||(d.row->>'part')||':'||(d.row->>'id'))::uuid
 CROSS JOIN LATERAL jsonb_array_elements(d.row->'options') AS o(value)
 ON CONFLICT(id) DO NOTHING RETURNING id
), linked AS (
 INSERT INTO public.intensive_exam_questions(exam_id,section_id,question_id,marks,position)
 SELECT 'cf9c621b-1611-fcb7-3f63-58542eb59774'::uuid,'1c1b2f62-58a6-3441-24c3-1757c802f415'::uuid,q.id,1,(d.row->>'position')::integer
 FROM dataset d JOIN questions_added q ON q.id=md5('NUMO:EL097:FINAL:'||(d.row->>'part')||':'||(d.row->>'id'))::uuid
 WHERE (d.row->>'key') IS NOT NULL
 ON CONFLICT DO NOTHING RETURNING id
)
SELECT (SELECT count(*) FROM questions_added) AS source_questions_imported,
 (SELECT count(*) FROM options_added) AS original_options_imported,
 (SELECT count(*) FROM linked) AS graded_questions_linked;